<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {findMyWindow,findMyCapabilities,findMyRows,findMyPoint,findMyDocument} from './findmy-state.js';
 import {permission} from './preferences-effects.js';
 import {findMyMenus} from './findmy-menus.js';
 import {createFindMyNativeView} from './findmy-native-view.js';
 import './findmy.css';
 let {state: findMyState,profile,window,windowId=window?.id,execute,registerView,sources={},available=true,active=true,controls={}}=$props();
 let root=$state(null),error=$state(''),menuId=$state(null),lostMessage=$state(''),lostPhone=$state(''),locationLabel=$state(''),latitude=$state(''),longitude=$state(''),itemName=$state(''),placeId=$state('');
 let originalState,originalProfile,originalWindow,originalId,facade,retired=false;
 const session=$derived(findMyWindow(findMyState,windowId)),cap=$derived(findMyCapabilities(profile)),allowed=$derived(!!sources.preferences&&permission(sources.preferences,'findmy','location'));
 const rows=$derived(session?findMyRows(findMyState,sources,session.tab):[]),visible=$derived(rows.filter(row=>row.name.toLocaleLowerCase('en-US').includes(session?.query.toLocaleLowerCase('en-US')??''))),selected=$derived(rows.find(row=>row.id===session?.selectedId)),position=$derived(selected?.position),map=$derived(session&&allowed?findMyDocument(findMyState,session,sources,false):null),menus=$derived(findMyMenus({state: findMyState,profile,windowId,context:{getShared:name=>sources[name]}})),openMenu=$derived(menus.find(menu=>menu.id===menuId));
 const current=()=>!retired&&root?.isConnected&&findMyState===originalState&&profile===originalProfile&&window===originalWindow&&windowId===originalId;
 async function command(suffix,payload={}){if(!current()||!available||!active)return;menuId=null;const response=await execute(`findmy.${suffix}`,{windowId},payload);if(current())error=response?.status==='applied'?'':response?.error?.message??response?.message??'The original native action is unavailable.';return response;}
 async function menuAction(item){if(!current()||!item.enabled||!item.request)return;menuId=null;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current())error=response?.status==='applied'?'':response?.error?.message??response?.message??'The native menu action is unavailable.';}
 function sheet(kind){lostMessage=position?.lostMessage??'';lostPhone=position?.lostPhone??'';locationLabel=selected?.location?.label??'';latitude=selected?.location?String(selected.location.latitude):'';longitude=selected?.location?String(selected.location.longitude):'';itemName='';placeId=sources.maps?.places[0]?.id??'';command('sheet',{sheet:kind});}
 function keyboard(event){if(event.key==='Escape'){if(menuId)command('menu.close');if(session?.sheet!=='none')command('sheet',{sheet:'none'});}const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier&&['1','2','3'].includes(event.key)){event.preventDefault();command('tab',{tab:['people','devices','items'][Number(event.key)-1]});}if(modifier&&['+','=','-'].includes(event.key)){event.preventDefault();command('zoom',{zoom:Math.max(1,Math.min(8,session.zoom+(event.key==='-'?-.5:.5)))});}if(modifier&&event.key.toLowerCase()==='p'){event.preventDefault();command('print');}if(modifier&&event.key.toLowerCase()==='f'){event.preventDefault();command('focus',{controlId:'search'});}}
 function addItem(){const place=sources.maps?.places.find(p=>p.id===placeId);if(place)command('item.add',{name:itemName,x:place.x,y:place.y,placeId:place.id});}
 onMount(()=>{originalState=findMyState;originalProfile=profile;originalWindow=window;originalId=windowId;facade=createFindMyNativeView({getRoot:()=>root,getState:()=>findMyState,getProfile:()=>profile,getWindow:()=>window,getSources:()=>sources,getMenu:()=>menuId,setMenu:id=>menuId=id,windowId,available:()=>current()&&available,tick});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
 $effect(()=>{const route=sources.sound?.outputs.find(output=>output.id===sources.sound.outputDeviceId);if(route){const snapshot={id:route.id,available:route.available,muted:route.muted,volume:route.volume};facade?.syncSound(snapshot);}if(!available)facade?.stopSound();});
 $effect(()=>{const kind=session?.sheet;if(kind==='lost'){lostMessage=position?.lostMessage??'';lostPhone=position?.lostPhone??'';}if(kind==='shareLocation'){locationLabel=selected?.location?.label??'';latitude=selected?.location?String(selected.location.latitude):'';longitude=selected?.location?String(selected.location.longitude):'';}if(kind==='addItem'){itemName='';placeId=sources.maps?.places[0]?.id??'';}});
</script>
<section bind:this={root} class="findmy-app" class:classic={cap.classic} class:golden={cap.golden} class:windows={cap.windows} data-findmy-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="findmy-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}<strong>{cap.label}</strong><button data-findmy-control="help" aria-label="Find My Help" onclick={()=>sheet('help')}>?</button></header>
 {#if cap.windows}<nav class="findmy-menubar" aria-label="Application menu">{#each menus as menu}<button data-findmy-control={`menu:${menu.id}`} disabled={!menu.enabled} aria-expanded={menuId===menu.id} onclick={()=>command(menuId===menu.id?'menu.close':'menu.open',menuId===menu.id?{}:{menuId:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if openMenu}<div class="findmy-menu" role="menu" aria-label={openMenu.label}>{#each openMenu.children as item}<button role="menuitem" disabled={!item.enabled} data-findmy-control={`menu-item:${item.id}`} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="findmy-content" inert={!active||!available||session.sheet!=='none'}>
 <aside class="findmy-sidebar">
 <nav class="findmy-tabs" aria-label="Find My categories">{#each ['people','devices','items'] as tab}<button data-findmy-control={`tab:${tab}`} class:selected={session.tab===tab} aria-pressed={session.tab===tab} onclick={()=>command('tab',{tab})}>{tab[0].toUpperCase()+tab.slice(1)}</button>{/each}</nav>
 <label class="findmy-search"><span aria-hidden="true">⌕</span><input data-findmy-control="search" type="search" aria-label={`Search ${session.tab}`} placeholder="Search" value={session.query} oninput={event=>command('search',{query:event.currentTarget.value})}/></label>
 <div class="findmy-list" data-findmy-area="list" role="listbox" aria-label={session.tab}>
 {#if session.tab==='me'}<div class="findmy-me"><div class="findmy-avatar">{sources.messages?.account.initials??'Me'}</div><h2>{sources.messages?.account.name??'Local User'}</h2><p>My Location</p><strong>{allowed?'Authored Harbor scene':'Location Services Off'}</strong><p>No host GPS or account tracking. Your Messages location sharing is maintained only in its original conversations.</p><button data-findmy-control="me:permission" onclick={()=>command('permission')}>Location Services…</button></div>
 {:else}{#each visible as row (row.id)}<button class="findmy-row" class:selected={session.selectedId===row.id} role="option" aria-selected={session.selectedId===row.id} data-findmy-control={`row:${row.id}`} onclick={()=>command('select',{id:row.id})}><span class:person={row.kind==='person'} class="findmy-row-icon" aria-hidden="true">{row.kind==='person'?row.name.split(/\s+/u).slice(0,2).map(s=>s[0]).join(''):row.kind==='item'?'▣':row.device?.kind==='keyboard'?'⌨':'◉'}</span><span><strong>{row.name}</strong><small>{row.kind==='person'?row.location?(allowed?row.location.label:'Location hidden · permission off'):'No location shared':row.position.found?'Authored local position':'No current local position'}</small>{#if row.position?.lost}<small class="findmy-lost-label">Local Lost Mode</small>{/if}</span></button>{/each}
 {#if !visible.length}<div class="findmy-empty-list"><strong>{session.query?'No Results':session.tab==='people'?'No People':'No Items'}</strong><p>{session.tab==='people'?'People come from original Contacts. Shared location is shown only when an actual Messages participant address matches a contact endpoint.':'Add an authored local item to see it here.'}</p></div>{/if}{/if}
 </div>
 <footer class="findmy-sidebar-footer"><button data-findmy-control="tab:me" class:selected={session.tab==='me'} onclick={()=>command('tab',{tab:'me'})}><span class="findmy-mini-avatar">●</span> Me</button><button data-findmy-control="item:add" aria-label="Add authored local item" disabled={!allowed} onclick={()=>sheet('addItem')}>＋</button></footer>
 </aside>
 <main class="findmy-map-pane" aria-label="Authored local Harbor map">
 {#if map}<div class="findmy-map-image">{@html map.content}</div>{:else}<div class="findmy-map-blocked"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="38"/><path d="M28 55L72 28 55 72 48 49Z"/></svg><h2>{sources.maps?'Location Services is Off':'Original map unavailable'}</h2><p>Grant explicit scene location access to display local positions.</p><button data-findmy-control="permission" onclick={()=>command('permission')}>Open Location Services…</button></div>{/if}
 <div class="findmy-map-toolbar"><button data-findmy-control="map:standard" class:selected={session.mode==='map'} disabled={!allowed} onclick={()=>command('mode',{mode:'map'})}>Map</button><button data-findmy-control="map:terrain" class:selected={session.mode==='satellite'} disabled={!allowed} onclick={()=>command('mode',{mode:'satellite'})}>Terrain</button><button data-findmy-control="map:share" aria-label="Share Map" disabled={!allowed} onclick={()=>command('share')}>↥</button></div>
 {#if allowed}<div class="findmy-map-pins" style={`--zoom:${session.zoom}`}>{#each rows as row (row.id)}{@const p=findMyPoint(row)}{#if p}<button class="findmy-map-pin" class:selected={row.id===session.selectedId} style={`left:${50+(p.x-session.center.x)*session.zoom/10}%;top:${50+(p.y-session.center.y)*session.zoom/9}%`} data-findmy-control={`pin:${row.id}`} aria-label={`Select ${row.name} on authored map`} onclick={()=>command('select',{id:row.id})}><span>{row.kind==='person'?row.name[0]:row.kind==='item'?'▣':'◉'}</span><small>{row.name}</small></button>{/if}{/each}</div>{/if}
 {#if selected}<div class="findmy-callout"><strong>{selected.name}</strong><small>{selected.kind==='person'?selected.location?(allowed?selected.location.label:'Location hidden'):'No location shared':position.found?'Authored local position':'No location found'}</small><button data-findmy-control="info" aria-label={`Show ${selected.name} information`} aria-expanded={session.details} onclick={()=>command('details',{visible:!session.details})}>ⓘ</button></div>{/if}
 <div class="findmy-map-navigation"><div class="findmy-pan"><button data-findmy-control="pan:up" aria-label="Pan North" disabled={!allowed} onclick={()=>command('pan',{x:session.center.x,y:Math.max(0,session.center.y-80/session.zoom)})}>↑</button><button data-findmy-control="pan:left" aria-label="Pan West" disabled={!allowed} onclick={()=>command('pan',{x:Math.max(0,session.center.x-80/session.zoom),y:session.center.y})}>←</button><button data-findmy-control="map:center" aria-label="Center Selection" disabled={!allowed} onclick={()=>command('center')}>⌖</button><button data-findmy-control="pan:right" aria-label="Pan East" disabled={!allowed} onclick={()=>command('pan',{x:Math.min(1000,session.center.x+80/session.zoom),y:session.center.y})}>→</button><button data-findmy-control="pan:down" aria-label="Pan South" disabled={!allowed} onclick={()=>command('pan',{x:session.center.x,y:Math.min(1000,session.center.y+80/session.zoom)})}>↓</button></div><div class="findmy-zoom"><button data-findmy-control="zoom:in" aria-label="Zoom In" disabled={!allowed||session.zoom>=8} onclick={()=>command('zoom',{zoom:Math.min(8,session.zoom+.5)})}>＋</button><button data-findmy-control="zoom:out" aria-label="Zoom Out" disabled={!allowed||session.zoom<=1} onclick={()=>command('zoom',{zoom:Math.max(1,session.zoom-.5)})}>−</button></div></div>
 {#if selected&&session.details}<section class="findmy-details" aria-label={`${selected.name} details`}><header><div class="findmy-detail-icon">{selected.kind==='person'?'●':selected.kind==='item'?'▣':'◉'}</div><div><h2>{selected.name}</h2><p>{selected.kind==='person'?selected.location?(allowed?selected.location.label:'Location hidden'):'No location shared':position.found?'Authored Harbor position':'No current local position'}{selected.device?.batteryPercent!==null&&selected.device?.batteryPercent!==undefined?` · ${selected.device.batteryPercent}%`:''}</p></div><button data-findmy-control="details:close" aria-label="Close Information" onclick={()=>command('details',{visible:false})}>×</button></header>
 {#if selected.kind==='person'}<div class="findmy-detail-actions"><button data-findmy-control="contact" onclick={()=>command('contact')}>Contact</button><button data-findmy-control="messages" onclick={()=>command('messages')}>Messages</button><button data-findmy-control="location:share" disabled={!allowed||!selected.conversation} onclick={()=>sheet('shareLocation')}>Share Location…</button></div><p class="findmy-detail-note">{selected.conversation?'Sharing belongs to the original Messages conversation. No duplicate person location is stored here.':'No original Messages conversation matches this contact’s email or phone. Open Messages to compose to that real address.'}</p>
 {:else}<div class="findmy-detail-actions"><button data-findmy-control="sound" disabled={!allowed||!position.found||selected.device&&!selected.device.available} onclick={()=>command('sound')}>♫<span>Play Sound</span></button><button data-findmy-control="maps" disabled={!allowed} onclick={()=>command('maps')}>➤<span>Directions</span></button></div><button class="findmy-detail-line" data-findmy-control="notify" disabled={!allowed} onclick={()=>sheet('notify')}><span>Notify When Found <small>Local authored transition only</small></span><strong>{position.notify?'On':'Off'} ›</strong></button><button class="findmy-detail-line" data-findmy-control="lost" disabled={!allowed} onclick={()=>sheet('lost')}><span>Mark As Lost <small>Local Lost Mode; no remote lock</small></span><strong>{position.lost?'Enabled':'Enable'} ›</strong></button><details class="findmy-simulation"><summary>Local scene controls</summary><p>No Bluetooth position measurement or Find My network is used.</p><button data-findmy-control="found" disabled={!allowed} onclick={()=>command('found',{found:!position.found})}>{position.found?'Mark Locally Unavailable':'Mark Locally Found'}</button><button data-findmy-control="sound:stop" onclick={()=>command('sound.stop')}>Stop Sound</button>{#if position.kind==='item'}<button class="destructive" data-findmy-control="remove" onclick={()=>sheet('remove')}>Remove Local Item…</button>{/if}</details>{/if}
 </section>{/if}
 <p class="findmy-map-attribution">Authored Harbor · not live geographic tiles</p>
 </main>
 </div>
 <footer class="findmy-status" role="status">{error||session.status||cap.disclosure}</footer>
 {#if session.sheet!=='none'}<div class="findmy-backdrop"><section class="findmy-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='lost'?'Local Lost Mode':session.sheet==='shareLocation'?'Share Authored Location':session.sheet==='notify'?'Notify When Found':session.sheet==='remove'?'Remove Local Item':session.sheet==='addItem'?'Add Local Item':'Find My Help'}>
 {#if session.sheet==='help'}<div class="findmy-help-icon">⌖</div><h2>{cap.label}</h2><p>{cap.disclosure}</p><p>{cap.mapDisclosure}</p><p>People are original Contacts with original Messages locations. Devices refer to the original Bluetooth device IDs. Sound plays real bundled audio on this computer, respecting original Sound volume and mute. Local Lost Mode and found notifications never lock, erase, track or contact another device.</p><div class="findmy-sheet-actions"><button data-findmy-control="help:permission" onclick={()=>command('permission')}>Location Services…</button><button data-findmy-control="sheet:done" onclick={()=>command('sheet',{sheet:'none'})}>Done</button></div>
 {:else if session.sheet==='permission'}<h2>Location Services</h2><p>Use the actual Security & Privacy permission sheet. No host permission is requested.</p><button data-findmy-control="permission:open" onclick={()=>command('permission')}>Open Original Settings…</button><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button>
 {:else if session.sheet==='lost'}<h2>Mark {selected?.name??'Item'} As Lost</h2><p>Retain a local recovery message and phone number. This does not remotely lock or erase a device.</p><label>Phone <input data-findmy-control="lost:phone" type="tel" maxlength="128" bind:value={lostPhone}/></label><label>Message <textarea data-findmy-control="lost:message" maxlength="1024" bind:value={lostMessage}></textarea></label>{#if position?.lost}<blockquote>{position.lostMessage}<br/>{position.lostPhone}</blockquote>{/if}<div class="findmy-sheet-actions"><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button>{#if position?.lost}<button data-findmy-control="lost:disable" onclick={()=>command('lost',{enabled:false,message:'',phone:''})}>Turn Off</button>{/if}<button class="primary" data-findmy-control="lost:confirm" disabled={!position} onclick={()=>command('lost',{enabled:true,message:lostMessage,phone:lostPhone})}>{position?.lost?'Save Local Message':'Enable Locally'}</button></div>
 {:else if session.sheet==='notify'}<h2>Notify When Found</h2><p>For {selected?.name??'this item'}, deliver an in-app notice when its local scene status changes from unavailable to found. No server notification or background tracking is claimed.</p><div class="findmy-sheet-actions"><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button><button class="primary" data-findmy-control="notify:confirm" disabled={!position} onclick={()=>command('notify',{enabled:!position.notify})}>{position?.notify?'Cancel Notification':'Enable Local Notification'}</button></div>
 {:else if session.sheet==='remove'}<h2>Remove {selected?.name??'Local Item'}?</h2><p>Remove only this authored local item and its local lost/notification settings. Original Bluetooth devices and Contact/Message records are untouched.</p><div class="findmy-sheet-actions"><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button><button class="destructive" data-findmy-control="remove:confirm" onclick={()=>command('remove',{confirmed:true})}>Remove Local Item</button></div>
 {:else if session.sheet==='addItem'}<h2>Add Local Item</h2><p>Add an authored item at an existing Harbor map place. No AirTag or tracker is paired.</p><label>Name <input data-findmy-control="item:name" maxlength="256" bind:value={itemName}/></label><label>Authored Place <select data-findmy-control="item:place" bind:value={placeId}>{#each sources.maps?.places??[] as place}<option value={place.id}>{place.name}</option>{/each}</select></label><div class="findmy-sheet-actions"><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button><button class="primary" data-findmy-control="item:confirm" disabled={!itemName.trim()||!placeId} onclick={addItem}>Add Local Item</button></div>
 {:else if session.sheet==='shareLocation'}<h2>Share Authored Location</h2><p>Forward explicit fictional world coordinates to the original selected Messages conversation. These are not host GPS and will be projected onto the local map.</p><label>Label <input data-findmy-control="location:label" maxlength="256" bind:value={locationLabel}/></label><label>Latitude <input data-findmy-control="location:latitude" type="number" min="-90" max="90" step="any" bind:value={latitude}/></label><label>Longitude <input data-findmy-control="location:longitude" type="number" min="-180" max="180" step="any" bind:value={longitude}/></label><div class="findmy-sheet-actions"><button data-findmy-control="sheet:cancel" onclick={()=>command('sheet',{sheet:'none'})}>Cancel</button>{#if selected?.location}<button data-findmy-control="location:stop" onclick={()=>command('location.share',{location:null})}>Stop Sharing</button>{/if}<button class="primary" data-findmy-control="location:confirm" disabled={!locationLabel.trim()||latitude===''||longitude===''} onclick={()=>command('location.share',{location:{label:locationLabel,latitude:Number(latitude),longitude:Number(longitude)}})}>Share in Messages</button></div>{/if}
 {#if error}<p class="findmy-error" role="alert">{error}</p>{/if}
 </section></div>{/if}
 {:else}<p role="alert">The original Find My window session is unavailable.</p>{/if}
</section>
